(async()=>{'use strict';const key='uhe-base-config-v1',nativeFetch=window.fetch.bind(window),status=document.getElementById('configStatus');let payload,compiled;
function fail(message){status.textContent=message;status.classList.add('notice')}
try{let local;try{local=JSON.parse(localStorage.getItem(key))}catch(e){}if(local){try{compiled=ConfigModel.compile(local);payload=local;status.textContent='Base: configuração local importada.'}catch(e){fail('Configuração local inválida. Usando a base publicada.')}}if(!compiled){const response=await nativeFetch('config.json',{cache:'no-cache'});if(!response.ok)throw Error('Configuração publicada indisponível');payload=await response.json();compiled=ConfigModel.compile(payload);status.textContent='Base: configuração publicada.'}
if(!compiled.sin.length){const published=await nativeFetch('config.json',{cache:'no-cache'}).then(r=>r.json());payload.sheets.UniversoSIN=published.sheets.UniversoSIN;compiled=ConfigModel.compile(payload)}
window.UHE_GET_PAYLOAD=()=>payload;
window.UHE_ACCEPT_PAYLOAD=next=>{const checked=ConfigModel.compile(next);payload=next;compiled=checked;window.UHE_SIN.splice(0,window.UHE_SIN.length,...checked.sin);Object.assign(window.UHE_CONFIG,checked.settings);localStorage.setItem(key,JSON.stringify(next));Engine.refs.splice(0,Engine.refs.length,...checked.refs);status.textContent='Base: planilha Google Sheets.'};
Engine.refs.splice(0,Engine.refs.length,...compiled.refs);window.UHE_CONFIG=compiled.settings;window.UHE_SIN=compiled.sin;
let hash=2166136261;for(const ch of JSON.stringify(payload)){hash^=ch.charCodeAt(0);hash=Math.imul(hash,16777619)}const revision=(hash>>>0).toString(16);window.UHE_CONFIG.revision=revision;
for(const [k,v] of Object.entries(compiled.settings.colors)){const vars={azul_escuro:'--ctg-dark',azul_medio:'--ctg-blue',azul_claro:'--ctg-light',verde:'--ctg-green',amarelo:'--ctg-orange'};document.documentElement.style.setProperty(vars[k],v)}
const overrides=new Map(['ctg.json','ctg-units.json'].map((f,i)=>[new URL(f,document.baseURI).href,i?compiled.units:compiled.plants]));window.fetch=async(input,options)=>{const url=typeof input==='string'||input instanceof URL?new URL(input,document.baseURI).href:input.url;if(overrides.has(url)&&(!options?.method||options.method==='GET'))return new Response(JSON.stringify(overrides.get(url)),{headers:{'Content-Type':'application/json'}});return nativeFetch(input,options)};
document.getElementById('year').value=compiled.settings.year;
for(const src of ['app.js','ctg-model.js','sheet-bridge.js','projection-model.js','projection.js','analysis.js','ctg.js'])await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=src;script.onload=resolve;script.onerror=()=>reject(Error('Falha ao carregar '+src));document.body.append(script)});
function saveFile(name,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
document.getElementById('configDownload').onclick=()=>saveFile('configuracao-ctg.json',payload);
document.getElementById('configRestore').onclick=()=>{if(!confirm('Voltar à configuração publicada? Os cenários de simulação serão mantidos.'))return;try{localStorage.removeItem(key);location.reload()}catch(e){fail('Não foi possível restaurar a configuração.')}};
document.getElementById('configImport').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024)throw Error('Limite de 2 MB.');const next=JSON.parse(await f.text());ConfigModel.compile(next);localStorage.setItem(key,JSON.stringify(next));location.reload()}catch(err){fail('Importação recusada: '+err.message)}finally{e.target.value=''}};
}catch(e){fail('Não foi possível iniciar: '+e.message)}
})();
